def exact(value, expected):
    """Compare JSON values including boolean/integer representation differences."""
    return json.dumps(value, sort_keys=True) == json.dumps(expected, sort_keys=True)


def inventory_tool_inputs(root):
    """Name the complete bounded Python tooling closure, without executing it."""
    scripts = root / "scripts"
    if scripts.is_symlink() or not scripts.is_dir():
        raise Incomplete("Inventory tooling directory is missing or linked.")
    names = {"policy/analysis-tools.json"}
    for path in scripts.rglob("*.py"):
        if "__pycache__" in path.parts:
            continue
        if path.resolve(strict=True) != path or not path.is_file():
            raise Incomplete("Inventory tooling contains a linked or nonregular input.")
        names.add(path.relative_to(root).as_posix())
        if len(names) > 128:
            raise Incomplete("Inventory tooling closure exceeds its fixed input allowance.")
    if not INVENTORY_REQUIRED_TOOLS <= names:
        raise Incomplete("Inventory tooling closure omits a required entry point.")
    return names


def inventory_admission_live(policy):
    """Reject future, expired or widened one-hour discovery admissions."""
    created, expires = policy.get("created_unix_seconds"), policy.get("expires_unix_seconds")
    if (type(created) is not int or type(expires) is not int or created <= 0
            or expires - created != 3600 or not created <= time.time() < expires):
        raise Incomplete("Inventory admission is not within its fixed one-hour validity window.")


# Current source-bound cohorts retain full per-invocation observations. The
# measured 213-row report exceeds16MiB; compact serialization removes duplicated
# whitespace without dropping evidence. This finite role limit covers current
# admitted cohorts; reassess it with future schema/output growth. Inventory cards
# and coordinator plans keep their separate512KiB allowance.
NATIVE_RECEIPT_MAX_BYTES = 64 * 1024 * 1024

# The current two complete-package source maps may repeat in every mutation row.
# Large current receipts keep their exact values in one self-contained table;
# raw64MiB admission, inventory roles and all expanded receipt validators remain.
SOURCE_VECTOR_MARKER = 'nevrotick_settled_rate_source_vectors'
SOURCE_VECTOR_REFERENCE = 'source_vector_sha256'
SOURCE_VECTOR_WIDTHS = {
    'settled_rate_complete_package_reservation': 2820,
    'achieved_phase_complete_package_reservation': 2765,
}
SOURCE_VECTOR_MAX_TABLE = 4
SOURCE_VECTOR_MAX_ROWS = 516
SOURCE_VECTOR_MAX_EXPANDED_ENTRIES = 3_000_000
SOURCE_VECTOR_MAX_JSON_DEPTH = 64


def _source_vector_digest(vector):
    """Hash the actual complete flat map, independently of dictionary order."""
    return hashlib.sha256(json.dumps(vector, sort_keys=True, separators=(',', ':'),
                                     allow_nan=False).encode('utf-8')).hexdigest()


def _checked_source_vector(vector, *, width=None):
    """Admit bounded ASCII keys and exact finite nonnegative integer values."""
    if (type(vector) is not dict or len(vector) not in set(SOURCE_VECTOR_WIDTHS.values())
            or (width is not None and len(vector) != width)
            or any(type(key) is not str or re.fullmatch(r'[A-Za-z_][A-Za-z0-9_.]{0,255}', key) is None
                   or key in {SOURCE_VECTOR_MARKER, SOURCE_VECTOR_REFERENCE}
                   or type(value) is not int or not 0 <= value < (1 << 63)
                   for key, value in vector.items())):
        raise Incomplete('Native source vector has an unreviewed width, key or integer.')
    return vector


def _current_rate_receipt_rows(report):
    """Select only the current two-map mutation role, leaving legacy roles alone."""
    if (type(report) is not dict or report.get('selected_lane') != 'mutation'
            or type(report.get('core_accounting_schema_version')) is not int
            or report['core_accounting_schema_version'] != 3
            or type(report.get('core_rate_delivery_reserved_totals')) is not dict
            or len(report['core_rate_delivery_reserved_totals']) != 55):
        raise Incomplete('Source-vector transport requires the current settled-rate mutation role.')
    rows = report.get('core_invocations')
    if (type(rows) is not list or not 1 <= len(rows) <= SOURCE_VECTOR_MAX_ROWS
            or any(type(row) is not dict for row in rows)):
        raise Incomplete('Source-vector receipt has an unreviewed invocation count or row.')
    return rows


def _source_vector_body_entries(body):
    """Bound the whole JSON tree and reject reference markers outside two slots.

    Entries count every dictionary pair and list item in the eventual receipt.
    Repeated references are charged separately by the caller before any vector
    expansion. Iteration avoids unbounded Python recursion on hostile input.
    """
    total = 0
    pending = [(body, ())]
    while pending:
        value, path = pending.pop()
        if len(path) > SOURCE_VECTOR_MAX_JSON_DEPTH:
            raise Incomplete('Native source-vector receipt JSON depth exceeds its bound.')
        if type(value) is dict:
            total += len(value)
            if total > SOURCE_VECTOR_MAX_EXPANDED_ENTRIES:
                raise Incomplete('Native receipt exceeds its expanded JSON-entry allowance.')
            if SOURCE_VECTOR_MARKER in value:
                raise Incomplete('Nested source-vector envelope is not admitted.')
            if SOURCE_VECTOR_REFERENCE in value and not (
                    len(path) == 3 and path[0] == 'core_invocations'
                    and type(path[1]) is int and path[2] in SOURCE_VECTOR_WIDTHS
                    and set(value) == {SOURCE_VECTOR_REFERENCE}):
                raise Incomplete('Source-vector reference occurs outside its two named fields.')
            entries = value.items()
        elif type(value) is list:
            total += len(value)
            if total > SOURCE_VECTOR_MAX_EXPANDED_ENTRIES:
                raise Incomplete('Native receipt exceeds its expanded JSON-entry allowance.')
            entries = enumerate(value)
        else:
            raise Incomplete('Native receipt JSON container is malformed.')
        for key, child in entries:
            if type(value) is dict and type(key) is not str:
                raise Incomplete('Native receipt JSON object key is not a string.')
            if type(child) in (dict, list):
                pending.append((child, (*path, key)))
            elif (child is not None and type(child) not in (str, bool, int, float)
                  or type(child) is float and not math.isfinite(child)):
                raise Incomplete('Native receipt contains a non-JSON or non-finite value.')
    return total


def pack_receipt_vectors(report):
    """Build the reviewed wire form without mutating any caller-owned facts.

    This force-wire helper is for an already oversized current report or finite
    codec controls. The writer below keeps every small/legacy report unchanged.
    Only the two explicitly named complete-package maps are replaced.
    """
    rows = _current_rate_receipt_rows(report)
    table, replacements = {}, []
    expanded_delta = 0
    for row in rows:
        replacement = dict(row)
        for field, width in SOURCE_VECTOR_WIDTHS.items():
            vector = _checked_source_vector(row.get(field), width=width)
            digest = _source_vector_digest(vector)
            if digest in table:
                if table[digest] != vector:
                    raise Incomplete('Different source vectors share an ambiguous canonical digest.')
            else:
                if len(table) >= SOURCE_VECTOR_MAX_TABLE:
                    raise Incomplete('Native receipt exceeds its four source-vector table entries.')
                table[digest] = dict(vector)
            replacement[field] = {SOURCE_VECTOR_REFERENCE: digest}
            expanded_delta += width - 1
        replacements.append(replacement)
    body = {**report, 'core_invocations': replacements}
    if _source_vector_body_entries(body) + expanded_delta > SOURCE_VECTOR_MAX_EXPANDED_ENTRIES:
        raise Incomplete('Native receipt exceeds its expanded JSON-entry allowance.')
    return {SOURCE_VECTOR_MARKER: 1, 'vectors': table, 'receipt': body}


def unpack_receipt_vectors(document):
    """Restore exact map values before the unchanged receipt-role validators.

    The table is self-contained. It never consults mutable current/historical
    recipe globals. Every occurrence gets a fresh map after all expansion bounds
    and reference identities have been admitted.
    """
    if type(document) is not dict or SOURCE_VECTOR_MARKER not in document:
        return document
    if (set(document) != {SOURCE_VECTOR_MARKER, 'vectors', 'receipt'}
            or type(document[SOURCE_VECTOR_MARKER]) is not int or document[SOURCE_VECTOR_MARKER] != 1):
        raise Incomplete('Native source-vector envelope schema is unknown or malformed.')
    table = document['vectors']
    if type(table) is not dict or not 1 <= len(table) <= SOURCE_VECTOR_MAX_TABLE:
        raise Incomplete('Native source-vector table is empty, malformed or too wide.')
    for digest, vector in table.items():
        if (type(digest) is not str or re.fullmatch(r'[0-9a-f]{64}', digest) is None
                or _source_vector_digest(_checked_source_vector(vector)) != digest):
            raise Incomplete('Native source-vector canonical digest disagrees with its full map.')
    body = document['receipt']
    rows = _current_rate_receipt_rows(body)
    used, expanded_delta = set(), 0
    for row in rows:
        for field, width in SOURCE_VECTOR_WIDTHS.items():
            reference = row.get(field)
            if (type(reference) is not dict or set(reference) != {SOURCE_VECTOR_REFERENCE}
                    or type(reference[SOURCE_VECTOR_REFERENCE]) is not str
                    or reference[SOURCE_VECTOR_REFERENCE] not in table):
                raise Incomplete('Native receipt has a missing, unknown or malformed source-vector reference.')
            digest = reference[SOURCE_VECTOR_REFERENCE]
            if len(table[digest]) != width:
                raise Incomplete('Native source-vector reference selects the wrong field width.')
            used.add(digest)
            expanded_delta += width - 1
    if used != set(table):
        raise Incomplete('Native source-vector table contains unused entries.')
    if _source_vector_body_entries(body) + expanded_delta > SOURCE_VECTOR_MAX_EXPANDED_ENTRIES:
        raise Incomplete('Native receipt exceeds its expanded JSON-entry allowance.')
    restored = []
    for row in rows:
        replacement = dict(row)
        for field in SOURCE_VECTOR_WIDTHS:
            replacement[field] = dict(table[row[field][SOURCE_VECTOR_REFERENCE]])
        restored.append(replacement)
    return {**body, 'core_invocations': restored}


def _finite_native_receipt_text(value):
    """Return compact finite JSON or reject an unrepresentable input value."""
    try:
        return json.dumps(value, separators=(',', ':'), allow_nan=False) + '\n'
    except (TypeError, ValueError, OverflowError, RecursionError) as error:
        raise Incomplete('Native verification receipt is not finite JSON.') from error


def encode_receipt_text(report):
    """Keep the existing64MiB raw limit and plain small/legacy JSON representation."""
    text = _finite_native_receipt_text(report)
    if len(text.encode('utf-8')) <= NATIVE_RECEIPT_MAX_BYTES:
        return text
    text = _finite_native_receipt_text(pack_receipt_vectors(report))
    if len(text.encode('utf-8')) > NATIVE_RECEIPT_MAX_BYTES:
        raise Incomplete('Native verification receipt exceeds its fixed byte allowance.')
    return text



def _core_json_document(path, *, role):
    """Decode one complete bounded regular JSON document under a closed role."""
    if type(role) is not str or role not in {"inventory", "native-receipt"}:
        raise Incomplete("Unreviewed core JSON document role.")
    maximum = 512 * 1024 if role == "inventory" else NATIVE_RECEIPT_MAX_BYTES
    label = "Inventory admission" if role == "inventory" else "Native mutation receipt"
    if path.resolve(strict=True) != path or not path.is_file():
        kind = "Inventory document" if role == "inventory" else "Native mutation receipt"
        raise Incomplete(kind + " is linked or nonregular.")
    with path.open("rb") as stream:
        data = stream.read(maximum + 1)
    if len(data) > maximum:
        raise Incomplete(label + " exceeds its fixed byte allowance.")

    def pairs(items):
        result = {}
        for name, value in items:
            if name in result:
                raise Incomplete(label + " contains a duplicate JSON field.")
            result[name] = value
        return result

    def constant(_value):
        raise Incomplete(label + " contains a non-finite JSON number.")

    def finite_float(token):
        value = float(token)
        if not math.isfinite(value):
            raise Incomplete(label + " contains a non-finite JSON number.")
        return value

    return json.loads(data, object_pairs_hook=pairs, parse_constant=constant,
                      parse_float=finite_float)


def inventory_document(path):
    """Keep inventory, coordinator-plan and configuration admission at 512 KiB."""
    return _core_json_document(path, role="inventory")


def native_receipt_document(path):
    """Read a complete native receipt under its finite64MiB byte allowance."""
    return unpack_receipt_vectors(_core_json_document(path, role="native-receipt"))


def admit_spent_contract_attempt():
    """Bind the one immutable failed attempt without granting any success credit.

    The entire first contracts vector is reserved despite its partial compiler
    coverage. Bounded receipt decoding and digest bookends admit only the retained
    delimiter failure; this is neither a resume API nor a new successful receipt.
    """
    prior = HISTORICAL_S148_COORDINATOR_COHORTS['spent_contract_attempt']
    path = Path(prior['receipt'])
    try:
        if (path.resolve(strict=True) != path or not path.is_file()
                or path.stat().st_size != prior['bytes']
                or PRODUCT.sha256(path) != prior['sha256']):
            raise Incomplete('The spent contract attempt receipt identity differs.')
        receipt = native_receipt_document(path)
        if path.stat().st_size != prior['bytes'] or PRODUCT.sha256(path) != prior['sha256']:
            raise Incomplete('The spent contract attempt receipt changed during admission.')
    except OSError as error:
        raise Incomplete('The spent contract attempt receipt is unavailable.') from error
    if (type(receipt) is not dict or receipt.get('status') != 'incomplete'
            or receipt.get('selected_lane') != 'contracts'
            or receipt.get('error') != 'Adaptive legal output is incomplete or has extra records.'
            or type(receipt.get('analysis_admission_after')) is not dict
            or receipt['analysis_admission_after'].get('unchanged') is not True):
        raise Incomplete('The spent contract attempt is not the retained incomplete harness result.')
    lanes = receipt.get('lanes')
    if type(lanes) is not list or len(lanes) != 29 or any(type(row) is not dict for row in lanes):
        raise Incomplete('The spent contract attempt command inventory differs.')
    legal = [row for row in lanes if row.get('lane') in
             ('external-legal-execution', 'external-adaptive-legal-execution')]
    negative = [row for row in lanes if type(row.get('lane')) is str
                and row['lane'].startswith('external-consumer-')
                and type(row.get('exit_code')) is int and row['exit_code'] != 0
                and row.get('failure') is None]
    if (len(legal) != 2 or {row['lane'] for row in legal} !=
            {'external-legal-execution', 'external-adaptive-legal-execution'}
            or any(type(row.get('exit_code')) is not int or row['exit_code'] != 0
                   or row.get('failure') is not None for row in legal)
            or len(negative) != 24):
        raise Incomplete('The spent contract attempt legal/negative execution counts differ.')
    return dict(prior)


def read_inventory_admission(root, path):
    """Bind one strict discovery document and every product/tool input byte.

    This accepts no campaign, coverage, contract or fuzz admission. The ordinary
    campaign policy and its source-count/critical-manifest checks remain intact.
    """
    root = Path(root).resolve(strict=True)
    path = Path(path)
    path = path if path.is_absolute() else root / path
    expected = root / INVENTORY_ADMISSION
    if path != expected or path.resolve(strict=True) != expected or not path.is_file():
        raise Incomplete("Use the exact canonical in-checkout inventory admission path.")
    policy = inventory_document(path)
    fields = {*INVENTORY_FIXED, "root", "created_unix_seconds", "expires_unix_seconds",
              "product_inputs_sha256", "tool_inputs_sha256"}
    if (not isinstance(policy, dict) or set(policy) != fields
            or any(not exact(policy.get(name), value) for name, value in INVENTORY_FIXED.items())
            or policy["root"] != str(root)):
        raise Incomplete("Unreviewed inventory-only schema, scope, root or allowance.")
    inventory_admission_live(policy)
    maps = ((policy["product_inputs_sha256"], set(INVENTORY_BOUND_INPUTS)),
            (policy["tool_inputs_sha256"], inventory_tool_inputs(root)))
    for identities, names in maps:
        if not isinstance(identities, dict) or set(identities) != names:
            raise Incomplete("Inventory-only input binding set differs from the complete admitted scope.")
        for name, digest in identities.items():
            source = root / name
            if (not isinstance(digest, str) or not re.fullmatch(r"[0-9a-f]{64}", digest)
                    or source.resolve(strict=True) != source or PRODUCT.sha256(source) != digest):
                raise Incomplete("Inventory-only source/tool input is unbound, linked or changed.")
    _, product = PRODUCT.admit_product(root)
    if (len(product) != INVENTORY_SOURCE_FILE_COUNT
            or set(product) != set(INVENTORY_BOUND_INPUTS)
            or product != policy["product_inputs_sha256"]):
        raise Incomplete("Inventory requires the exact current complete product and dependency graph.")
    return policy


def historical_admit_core_equivalence_scope(entries):
    """Allow empty or an exact reviewed principal/legacy closed fault set.

    The shared reader additionally checks the full descriptors, candidate,
    source/proof bytes and independent review references. Campaign accounting
    must still observe each exact fault as missed before subtracting it.
    """
    if not isinstance(entries, list) or len(entries) not in (0, 1, 3, 7):
        raise Incomplete('Core equivalence scope is not one reviewed closed set.')
    if not entries:
        return
    if len(entries) == 1:
        entry = entries[0]
        if (not isinstance(entry, dict) or entry.get('id') != 'S13-P-E-001'
                or entry.get('source_sha256') != '876b647b1d8f1df7156b7383c42fcc0a0a3497e0561ebb331079c120888da658'
                or not isinstance(entry.get('mutant'), dict)
                or entry['mutant'].get('name') != 'crates/time-core/src/principal.rs:945:17: replace < with <= in updated_score'
                or entry['mutant'].get('file') != HISTORICAL_LIFECYCLE_SUBJECTS['principal']
                or entry['mutant'].get('replacement') != '<='
                or not isinstance(entry.get('proof'), dict)
                or entry['proof'].get('path') != 'tasks/s1.3-principal-equivalences.md'):
            raise Incomplete('Principal floor equivalence differs from its exact reviewed boundary.')
        return
    if any(not isinstance(entry, dict) or not isinstance(entry.get('id'), str)
           or not isinstance(entry.get('mutant'), dict)
           or not isinstance(entry['mutant'].get('name'), str)
            or not isinstance(entry['mutant'].get('file'), str)
            or not isinstance(entry['mutant'].get('replacement'), str)
           or not isinstance(entry.get('proof'), dict)
           for entry in entries):
        raise Incomplete('Core equivalence identities are malformed.')
    selection_ids = set(CORE_EQUIVALENCE_IDENTITIES)
    combined_ids = selection_ids | set(ENCLOSURE_EQUIVALENCE_IDENTITIES)
    identifiers = {entry['id'] for entry in entries}
    if len(identifiers) != len(entries) or identifiers not in (selection_ids, combined_ids):
        raise Incomplete('Core equivalence identities are not one complete reviewed closed set.')
    for entry in entries:
        identifier = entry['id']
        selection = identifier in selection_ids
        identities = CORE_EQUIVALENCE_IDENTITIES if selection else ENCLOSURE_EQUIVALENCE_IDENTITIES
        source = CORE_EQUIVALENCE_SOURCE if selection else ENCLOSURE_EQUIVALENCE_SOURCE
        proof = CORE_EQUIVALENCE_PROOF if selection else ENCLOSURE_EQUIVALENCE_PROOF
        filename = HISTORICAL_SUBJECTS['selection'] if selection else HISTORICAL_SUBJECTS['enclosure']
        if (entry['mutant']['name'] != identities[identifier]
                or entry['mutant']['file'] != filename
                or entry['mutant']['replacement'] != CORE_EQUIVALENCE_REPLACEMENTS[identifier]
                or entry.get('source_sha256') != source or entry['proof'].get('path') != proof):
            raise Incomplete('Core equivalence identity, file, operator, own source or maintained proof differs.')


