def historical_s152b_admit_core_equivalence_scope(entries):
    """Close scope to eight exact reviewed descriptors, never pre-crediting E.

    The common admission checks current candidate/source/proof bytes, and the
    native receiver must independently observe each exact current mutant MISS.
    Before independent review/candidate binding, all nonempty sets fail closed.
    """
    if type(entries) is list and not entries and not HISTORICAL_S152B_MUTATION_INVENTORIES:
        return
    required = {'id', 'candidate_sha256', 'source_sha256', 'mutant', 'requirement', 'rationale', 'proof'}
    if (type(S152B_EQUIVALENCE_CANDIDATE) is not str
            or re.fullmatch(r'[0-9a-f]{64}', S152B_EQUIVALENCE_CANDIDATE) is None
            or type(entries) is not list or len(entries) != len(S152B_EQUIVALENCE_MUTANTS)):
        raise Incomplete('S152b exact reviewed eight-entry equivalence scope remains pending.')
    seen = set()
    for entry in entries:
        if type(entry) is not dict or set(entry) != required:
            raise Incomplete('S152b equivalence record has missing or unknown fields.')
        identifier = entry['id']
        if (type(identifier) is not str or identifier not in S152B_EQUIVALENCE_MUTANTS
                or identifier in seen or type(entry['mutant']) is not dict
                or COMMON.canonical_sha256(entry['mutant']) != S152B_EQUIVALENCE_MUTANTS[identifier]
                or entry['candidate_sha256'] != S152B_EQUIVALENCE_CANDIDATE
                or entry['source_sha256'] != S152B_EQUIVALENCE_SOURCES.get(entry['mutant'].get('file'))
                or entry['requirement'] != 'CHECK-7/8/14/25'
                or type(entry['rationale']) is not str or not 0 < len(entry['rationale'].strip()) <= 4096):
            raise Incomplete('S152b equivalence identity, full descriptor or candidate differs from review.')
        expected_proof = {'path': 'tasks/s1.3-combination-equivalences.md',
                          'sha256': S152B_EQUIVALENCE_PROOF, 'section': identifier,
                          'reviewer': 'root; adaptive_contract_review',
                          'verdict': 'independently-justified-equivalent'}
        if not exact(entry['proof'], expected_proof):
            raise Incomplete('S152b equivalence proof, section or independent review differs from admission.')
        seen.add(identifier)
    if seen != set(S152B_EQUIVALENCE_MUTANTS):
        raise Incomplete('S152b equivalence set is incomplete or duplicated.')


