def chart_composition_budget_vector(*, include_doctests=False, external_legal=False,
                                    prior_budget=None, fixture_delta=None):
    """Reserve the disjoint composition scalar/adaptor family without observations."""
    if (type(include_doctests) is not bool or type(external_legal) is not bool
            or (include_doctests and external_legal)):
        raise Incomplete('Ambiguous chart-composition source reservation.')
    if prior_budget is None:
        package, checks, _ = historical_s14a_cohort_budget_vectors(require_limits=False)
        prior_budget = checks['contracts'] if external_legal else package if include_doctests else checks['coverage']
    if fixture_delta is None:
        fixture_delta = chart_composition_fixture_budget(external_legal=external_legal)
    try:
        if external_legal:
            owner = CHART.CompositionContractOwner(
                fields=tuple(CHART_CONTRACTS.COMPOSITION_FIELDS),
                expected=CHART_CONTRACTS.composition_legal_expected,
                source=CHART_CONTRACTS.composition_legal_source)
            return CHART.composition_external_reservation(prior_budget, fixture_delta, owner)
        return CHART.composition_package_reservation(prior_budget, fixture_delta)
    except CHART.Incomplete as error:
        raise Incomplete(str(error)) from error


def chart_composition_complete_budget(*, include_doctests=False, external_legal=False):
    """Keep all2700 prior keys and add genuine fixtures plus the40-field extension."""
    package, checks, _ = historical_s14a_cohort_budget_vectors(require_limits=False)
    prior = checks['contracts'] if external_legal else package if include_doctests else checks['coverage']
    delta = chart_composition_fixture_budget(external_legal=external_legal)
    supplement = chart_composition_budget_vector(
        include_doctests=include_doctests, external_legal=external_legal,
        prior_budget=prior, fixture_delta=delta)
    try:
        return CHART.preserve_composition_extension(prior, delta, supplement)
    except CHART.Incomplete as error:
        raise Incomplete(str(error)) from error


